// Generated-code versions (F64 V0): the generator version, content hashes and the header every generated file starts with.
// Pure TypeScript (no Angular). docs/02-engine/codegen-typescript.md § Versions
import type { GeneratedFile } from './adapters/typescript/emit';
import { lineCommentOf } from '../languages/detect';
import { languageById } from '../languages/languages';
import { CODEGEN_LANGUAGES } from '../languages/support';

/**
 * The generator version, stamped into every generated file. Bump it when lowering or printing changes the output for the
 * same blueprint (the golden files in app/codegen-golden change): patch for formatting or comments, minor for new
 * constructs or helpers, major when generated signatures or file layout change. See docs/02-engine/codegen-typescript.md.
 */
export const CODEGEN_VERSION = '4.0.0';

export const STAMP_PREFIX = '// Generated by Rabbinatix';
/** a header line: `//` in TypeScript, JavaScript, C# and Java, `#` in Python; PHP's sits on its `<?php` line */
export const STAMP_START = /^(?:<\?php )?(?:\/\/|#) Generated by (?:Rabbinatix|Flow Weaver|ContractMap)/;
export const isStamped = (content: string) => STAMP_START.test(content);
/** the line comment of a generated file, by its name */
export const commentOf = (name: string) => lineCommentOf(name);
/** what a header starts with: the line comment, and in PHP the `<?php` it must come after */
export const stampCommentOf = (name: string) => (name.endsWith('.php') ? `<?php ${lineCommentOf(name)}` : lineCommentOf(name));
/** characters of the hash shown in the header (the full hash is recorded with the export) */
export const SHORT_HASH = 12;

/** what a generated file was made from */
export type StampSource =
  | { kind: 'logic'; key: string; version?: string; revision?: number; unsaved?: boolean }
  | { kind: 'system'; slug: string }
  | { kind: 'package'; name: string; version: string };

// ---------- SHA-256 ----------

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);
const ror = (x: number, n: number) => (x >>> n) | (x << (32 - n));
const hex = (bytes: ArrayLike<number>) => Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');

/** SHA-256 of the UTF-8 text, hex. Synchronous (headers are stamped while generating); matches Web Crypto. */
export function sha256Hex(text: string): string {
  const bytes = new TextEncoder().encode(text);
  const len = bytes.length;
  const size = ((len + 9 + 63) >> 6) << 6;
  const buf = new Uint8Array(size);
  buf.set(bytes);
  buf[len] = 0x80;
  const dv = new DataView(buf.buffer);
  dv.setUint32(size - 8, Math.floor(len / 0x20000000));
  dv.setUint32(size - 4, (len << 3) >>> 0);
  const H = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
  const W = new Uint32Array(64);
  for (let off = 0; off < size; off += 64) {
    for (let i = 0; i < 16; i++) W[i] = dv.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const a = W[i - 15], b = W[i - 2];
      W[i] = (W[i - 16] + (ror(a, 7) ^ ror(a, 18) ^ (a >>> 3)) + W[i - 7] + (ror(b, 17) ^ ror(b, 19) ^ (b >>> 10))) | 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (ror(e, 6) ^ ror(e, 11) ^ ror(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + W[i]) | 0;
      const t2 = ((ror(a, 2) ^ ror(a, 13) ^ ror(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] += a; H[1] += b; H[2] += c; H[3] += d; H[4] += e; H[5] += f; H[6] += g; H[7] += h;
  }
  return Array.from(H, (x) => x.toString(16).padStart(8, '0')).join('');
}

/** SHA-256 with Web Crypto when available (browsers), the synchronous version otherwise (tests, old runtimes). */
export async function sha256(text: string): Promise<string> {
  const subtle = typeof crypto !== 'undefined' ? crypto.subtle : undefined;
  if (subtle && typeof TextEncoder !== 'undefined') {
    try {
      return hex(new Uint8Array(await subtle.digest('SHA-256', new TextEncoder().encode(text))));
    } catch {
      /* insecure context: fall through */
    }
  }
  return sha256Hex(text);
}

// ---------- headers ----------

export function sourceText(s: StampSource): string {
  if (s.kind === 'system') return `system ${s.slug}`;
  if (s.kind === 'package') return `package ${s.name}@${s.version}`;
  const rev = s.revision !== undefined ? `r${s.revision}${s.unsaved ? ' + unsaved' : ''}` : '';
  return `logic ${s.key}${s.version ? ` v${s.version}${rev ? ` (${rev})` : ''}` : rev ? ` ${rev}` : ''}`;
}

export const stampLine = (source: string, hash: string, generator = CODEGEN_VERSION, comment = '//') =>
  `${comment} Generated by Rabbinatix · ${source} · codegen ${generator} · sha256:${hash.slice(0, SHORT_HASH)} · do not edit`;

/** the generator's languages, and JavaScript (the verification build) */
const STAMPABLE = [...CODEGEN_LANGUAGES, 'javascript'].flatMap((id) => languageById(id)?.extensions ?? []);
const isStampable = (name: string) => STAMPABLE.some((x) => name.endsWith(x));
const firstLine = (content: string) => content.slice(0, content.indexOf('\n') === -1 ? content.length : content.indexOf('\n'));

/** the content without its header line: what the hash covers */
export function bodyOf(content: string): string {
  if (!isStamped(content)) return content;
  const nl = content.indexOf('\n');
  return nl === -1 ? '' : content.slice(nl + 1);
}

/** Put the header on top of a file: replaces an existing `// Generated by Rabbinatix…` line, or adds one. */
export function stampContent(content: string, source: string, comment = '//'): { content: string; added: boolean; hash: string } {
  // a PHP file's bare `<?php` line becomes the header line
  const php = comment.startsWith('<?php') && !isStamped(content) && /^<\?php\r?\n/.test(content);
  const added = !isStamped(content) && !php;
  const body = php ? content.slice(content.indexOf('\n') + 1) : bodyOf(content);
  const hash = sha256Hex(body);
  return { content: `${stampLine(source, hash, CODEGEN_VERSION, comment)}\n${body}`, added, hash };
}

/** Stamp generated source files (every generator language, and JavaScript). Source maps shift by one line where a header was added rather than replaced. */
export function stampFiles(files: GeneratedFile[], sourceOf: (f: GeneratedFile) => StampSource | undefined): GeneratedFile[] {
  return files.map((f) => {
    const src = isStampable(f.name) ? sourceOf(f) : undefined;
    if (!src) return f;
    const r = stampContent(f.content, sourceText(src), stampCommentOf(f.name));
    return { ...f, content: r.content, map: r.added ? f.map.map((e) => ({ ...e, startLine: e.startLine + 1, endLine: e.endLine + 1 })) : f.map };
  });
}

/** Re-hash files that already carry a header (after formatting changed their text). */
export function restampFiles(files: GeneratedFile[]): GeneratedFile[] {
  return files.map((f) => {
    const p = isStamped(f.content) ? parseStamp(firstLine(f.content)) : undefined;
    return p?.source ? { ...f, content: stampContent(f.content, p.source, stampCommentOf(f.name)).content } : f;
  });
}

/** sha256 of what a recorded file covers: the body for stamped files, the whole text otherwise */
export const fileHash = (content: string) => sha256Hex(bodyOf(content));

// ---------- reading a header back ----------

export interface ParsedStamp {
  /** the raw source part, e.g. `logic LOGIC-AUTH-LOGIN-001 v1.3.0 (r12)` */
  source?: string;
  kind?: StampSource['kind'];
  key?: string;
  version?: string;
  revision?: number;
  unsaved?: boolean;
  generator?: string;
  /** hex, possibly shortened */
  hash?: string;
  /** a whole file was pasted: the hash of its body, to tell local edits apart */
  bodyHash?: string;
}

const STAMP_RE = /Generated by (?:Rabbinatix|Flow Weaver|ContractMap) · (.+?) · codegen ([^\s·]+) · sha256:([0-9a-f]+)/i;
const SOURCE_RE = /^(logic|system|package) (\S+)(?: v(\S+?))?(?: \(?r(\d+)( \+ unsaved)?\)?)?$/;

/** Read a pasted header line, a whole generated file, or a bare hash (`sha256:ab12…` or hex). */
export function parseStamp(text: string): ParsedStamp | undefined {
  const t = text.trim();
  if (!t) return undefined;
  const m = STAMP_RE.exec(t);
  if (m) {
    const out: ParsedStamp = { source: m[1], generator: m[2], hash: m[3].toLowerCase() };
    const s = SOURCE_RE.exec(m[1]);
    if (s) {
      out.kind = s[1] as StampSource['kind'];
      if (out.kind === 'package') {
        const at = s[2].lastIndexOf('@');
        out.key = at > 0 ? s[2].slice(0, at) : s[2];
        out.version = at > 0 ? s[2].slice(at + 1) : undefined;
      } else {
        out.key = s[2];
        out.version = s[3];
        out.revision = s[4] ? +s[4] : undefined;
        out.unsaved = !!s[5];
      }
    }
    // a whole file: its first line is the header, the rest is what the hash covers
    const whole = text.replace(/^\s+/, '');
    const nl = whole.indexOf('\n');
    if (nl > 0 && /Generated by (?:Rabbinatix|Flow Weaver|ContractMap)/.test(whole.slice(0, nl)) && whole.slice(nl + 1).trim()) out.bodyHash = sha256Hex(whole.slice(nl + 1));
    return out;
  }
  const h = /^(?:sha256:)?([0-9a-f]{7,64})$/i.exec(t);
  return h ? { hash: h[1].toLowerCase() } : undefined;
}

